# Pins are exact versions, resolved when written; never run a bare "mise use".
# Tools only the developer laptop needs (MISE_ENV=dev).

[tools]
# >>> mise
actionlint = { version = "1.0.0" }
dprint     = { version = "1.0.0" }
gitleaks   = { version = "1.0.0" }
grype      = { version = "1.0.0" }
jq         = { version = "1.0.0" }
# The PyPI name really is graphifyy, double y.
"pipx:graphifyy" = { uvx = true, version = "1.0.0" }
pre-commit       = { version = "1.0.0" }
shellcheck       = { version = "1.0.0" }
shfmt            = { version = "1.0.0" }
taplo            = { version = "1.0.0" }
# The tool-config script runs on it.
node = { version = "1.0.0" }
# mise's pipx backend installs through uv, and uv needs a Python >= 3.10 to lock graphifyy's dependencies.
python = { version = "1.0.0" }
uv     = { version = "1.0.0" }
# <<< mise

.config/mise/tasks/_scripts/checks.content:
#!/usr/bin/env bash

#MISE description="Predicates the merge tasks ask before touching a branch"
#MISE hide=true

# Each predicate answers by exit status and prints nothing; the caller owns the wording.

# Tracked files with modifications, staged or not.
has_uncommitted_changes() {
  [ -n "$(git status --porcelain)" ]
}

# Files git is not tracking and .gitignore does not cover.
has_untracked_files() {
  [ -n "$(git ls-files --others --exclude-standard)" ]
}

# A branch with no upstream, so "unpushed" cannot be measured against anything.
# Defaults to the branch you are standing on.
is_local_branch() {
  local branch="${1:-HEAD}"
  ! git rev-parse --abbrev-ref "${branch}@{u}" >/dev/null 2>&1
}

# Commits on ONE branch that its upstream does not have — never the repo-wide form.
has_unpushed_commits() {
  local branch="${1:-HEAD}"
  [ -n "$(git log --oneline "${branch}@{u}..${branch}" 2>/dev/null)" ]
}

# Whether this is a linked worktree rather than the main checkout.
is_git_worktree() {
  local git_dir git_common_dir
  # `|| var=''` keeps `set -e` from firing outside a repo.
  git_dir=$(git rev-parse --git-dir 2>/dev/null) || git_dir=''
  git_common_dir=$(git rev-parse --git-common-dir 2>/dev/null) || git_common_dir=''
  [ "${git_dir}" != "${git_common_dir}" ]
}

# The absolute path of the main worktree, which `git worktree list` prints first.
get_main_worktree_path() {
  git worktree list --porcelain | awk 'NR==1{sub(/^worktree /, ""); print; exit}'
}

.config/mise/tasks/_scripts/helpers.mjs.content:
#!/usr/bin/env node

// MISE description="Helper functions for Node-based mise tasks"
// MISE hide=true

// The `.mjs` mirror of `_scripts/helpers` — keep the two in step.

import { spawnSync } from "node:child_process";

// Style
const BOLD = "\x1B[1m";
const NORMAL = "\x1B[0m";
// Colors
const GREEN = "\x1B[0;32m";
const YELLOW = "\x1B[0;33m";
const RED = "\x1B[0;31m";
export const BLUE = "\x1B[0;34m";

/**
 * A full-width separator line built from the given character.
 * @param {string} char
 */
export function line_sep(char = "=") {
  const columns = process.stdout.columns || 80;
  process.stdout.write(`${char.repeat(columns)}\n`);
}

/**
 * A major section: a full-width `=` rule, then the title.
 * @param {string} msg
 */
export function print_header(msg) {
  line_sep("=");
  process.stdout.write(`${GREEN}${BOLD}${msg}${NORMAL}\n`);
}

/**
 * A step inside a section: a full-width `-` rule, then the title.
 * @param {string} msg
 */
export function print_subheader(msg) {
  line_sep("-");
  process.stdout.write(`${GREEN}${BOLD}${msg}${NORMAL}\n`);
}

/** @param {string} msg */
export function print_success(msg) {
  process.stdout.write(`${GREEN}${BOLD}${msg}${NORMAL}\n`);
}

export function print_ok() {
  process.stdout.write(`${GREEN}${BOLD}OK${NORMAL}\n`);
}

/** @param {string} msg */
export function print_wait(msg) {
  process.stdout.write(`${YELLOW}${BOLD}${msg}${NORMAL}`);
}

/** @param {string} msg */
export function print_warn(msg) {
  process.stdout.write(`${YELLOW}${BOLD}${msg}${NORMAL}\n`);
}

/** @param {string} msg */
export function print_yellow(msg) {
  process.stdout.write(`${YELLOW}${msg}${NORMAL}\n`);
}

export function print_newline() {
  process.stdout.write("\n");
}

/** Errors go to stderr, matching the bash library. @param {string} msg */
export function print_error(msg) {
  process.stderr.write(`${RED}${BOLD}${msg}${NORMAL}\n`);
}

/**
 * Run a command, inheriting stdio, and exit this task with its status when it
 * fails. The bash library needs no equivalent — `set -e` is it.
 *
 * @param {string} cmd
 * @param {string[]} args
 */
export function run(cmd, args = []) {
  const result = spawnSync(cmd, args, { stdio: "inherit" });

  if (result.error) {
    print_error(`Failed to spawn: ${cmd}`);
    print_error(result.error.message);
    process.exit(1);
  }

  if (result.signal) {
    print_error(`${cmd} was killed by signal ${result.signal}`);
    process.exit(1);
  }

  if (result.status !== 0) {
    print_error(`${cmd} exited with code ${result.status}`);
    process.exit(result.status ?? 1);
  }
}
